ximos" value="<?= h($st['estudios_proximos']??'') ?>"></label><label>Fecha del estudio<input type="datetime-local" name="fecha_estudio_programado" value="<?= !empty($st['fecha_estudio_programado'])?date('Y-m-d\TH:i',strtotime($st['fecha_estudio_programado'])):'' ?>"></label><label class="ancho">Observaciones<textarea name="observaciones_enfermeria_medica"><?= h($st['observaciones_enfermeria_medica']??'') ?></textarea></label></div><button class="boton principal">Guardar actualización</button></form></div><?php require '../../includes/footer.php'; ?>
